   119	template <typename T>
   120	struct LookupSegmentArray
   121	{
   122	  inline const T* get_value (hb_codepoint_t glyph_id, const void *base) const
   123	  {
   124	    return first <= glyph_id && glyph_id <= last ? &(base+valuesZ)[glyph_id - first] : nullptr;
   125	  }
   126	
   127	  inline int cmp (hb_codepoint_t g) const {
   128	    return g < first ? -1 : g <= last ? 0 : +1 ;
   129	  }
